#ifndef BURNOUT_ORDINAL_NAMES_H
#define BURNOUT_ORDINAL_NAMES_H
#include <stdint.h>
#include <stddef.h>

/* A19 -- ordinal -> name table for the DLLs the game resolves by ordinal.
 *
 * The table itself is generated by tools/gen_ordinal_names.py from the export
 * tables of the PE32 reference DLLs in the reference DLLs of a Wine/Proton prefix (the
 * Wine/Proton builds of the game's own prefix).  No name is guessed: an
 * ordinal that has no name in the reference export table is absent here, and
 * runtime/static_entry.c keeps it as a named stop.
 *
 * Lookup is by (DLL, ordinal); the DLL name is compared case-insensitively
 * because the game mixes "XINPUT1_3.dll" and "xinput1_3.dll".
 * Returns NULL when the pair is unknown. */
typedef struct {
    const char *dll;
    uint32_t ordinal;
    const char *name;
} OrdinalName;

extern const OrdinalName g_ordinal_names[];
extern const uint32_t g_ordinal_name_count;

const char *ordinal_name_lookup(const char *dll, uint32_t ordinal);

#endif
